import sys
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def display(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14 * self.radius * self.radius

    def display(self):
        pass

class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def area(self):
        return self.length * self.width

    def display(self):
        pass

def process_shape(shape_ptr, cast_type):
    if cast_type == 'circle':
        if isinstance(shape_ptr, Circle):
            print(f"Area: {shape_ptr.area()}")
        else:
            print("Invalid cast")
    elif cast_type == 'rectangle':
        if isinstance(shape_ptr, Rectangle):
            print(f"Area: {shape_ptr.area()}")
        else:
            print("Invalid cast")

def main():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return

    type_line = lines[0].strip()
    if type_line == 'circle':
        radius = float(lines[1].strip()) if len(lines) > 1 else 0
        shape = Circle(radius)
    elif type_line == 'rectangle':
        parts = lines[1].strip().split() if len(lines) > 1 else []
        length = float(parts[0]) if len(parts) > 0 else 0
        width = float(parts[1]) if len(parts) > 1 else 0
        shape = Rectangle(length, width)
    else:
        return

    cast_type = lines[2].strip() if len(lines) > 2 else ''
    process_shape(shape, cast_type)

if __name__ == "__main__":
    main()
